def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Repeated isolated cells are placement markers.
    marker_color, best = None, -1
    for color in counts:
        if color == bg:
            continue
        isolated = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                if not any(0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color
                           for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                    isolated += 1
        if isolated > best:
            marker_color, best = color, isolated

    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color]
    motif = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker_color]
    if not markers or not motif:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c, v in motif), max(r for r, c, v in motif)
    c0, c1 = min(c for r, c, v in motif), max(c for r, c, v in motif)
    cr, cc = (r0 + r1) // 2, (c0 + c1) // 2
    offsets = [(r-cr, c-cc, v) for r, c, v in motif]

    out = [row[:] for row in grid]
    for r, c in markers:
        out[r][c] = bg
    for r, c in markers:
        for dr, dc, color in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                out[nr][nc] = color
    return out
